  function posPage(){
    const b=branch(ui.posBranch),products=[...new Map(data.inventory.filter(x=>x.branch===ui.posBranch).map(x=>[x.sku,x])).values()];
    const lines=Object.keys(ui.cart).map(sku=>{const p=products.find(x=>x.sku===sku);return p?{p:p,qty:ui.cart[sku]}:null;}).filter(Boolean);
    const total=lines.reduce((sum,x)=>sum+x.p.price*x.qty,0),count=lines.reduce((sum,x)=>sum+x.qty,0);
    return '<div class="page-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span> COUNTER SALES</div><h1>Point of <span>sale.</span></h1><p>Fast checkout with branch-specific inventory and recorded payment method.</p></div><div class="heading-actions"><select class="branch-select" data-change="pos-branch" aria-label="POS branch">'+BRANCHES.map(x=>'<option value="'+x.id+'" '+(ui.posBranch===x.id?"selected":"")+'>'+esc(x.name)+'</option>').join("")+'</select><span class="live-tag"><i></i> Demo terminal</span></div></div><div class="pos-layout"><section class="panel pos-products"><div class="panel-heading"><div><span class="panel-kicker">PRODUCT CATALOGUE</span><h3>Available at '+esc(b.name)+'</h3><p>Select products to add them to the counter basket.</p></div><span class="muted-badge">'+products.length+' product lines</span></div><div class="pos-product-grid">'+products.map(p=>'<article class="pos-product-card"><div class="pos-product-visual '+(p.category==="Poultry"?"poultry":p.category==="Sausages"?"sausage":p.category==="Premium cuts"?"premium":"beef")+'"><span class="pos-product-icon">'+icon(p.category==="Poultry"?"drumstick":p.category==="Sausages"?"utensils":"beef")+'</span><small>'+esc(p.category)+'</small></div><div class="pos-product-content"><strong>'+esc(p.name)+'</strong><span>'+money(p.price)+' / '+esc(p.unit)+'</span><small class="'+(p.qty<=p.threshold?"text-danger":"")+'">'+num(p.qty)+' '+esc(p.unit)+' available</small><button class="btn btn-primary btn-small" data-action="pos-add" data-id="'+esc(p.sku)+'" '+(p.qty<=0?"disabled":"")+'>'+icon("plus")+' Add to sale</button></div></article>').join("")+'</div></section><aside class="panel pos-cart"><div class="panel-heading"><div><span class="panel-kicker">CURRENT SALE</span><h3>Counter basket</h3><p>'+esc(b.name)+' · sample checkout</p></div><span class="cart-count">'+count+'</span></div><label class="pos-customer-label">CUSTOMER / REFERENCE<input id="pos-customer" placeholder="Walk-in sale" value="Walk-in sale"></label><div class="cart-lines">'+(lines.length?lines.map(x=>'<div class="cart-line"><div class="cart-item-info"><strong>'+esc(x.p.name)+'</strong><small>'+money(x.p.price)+' × '+x.qty+' '+esc(x.p.unit)+'</small></div><div class="cart-line-controls"><button data-action="pos-dec" data-id="'+esc(x.p.sku)+'" class="cart-step" aria-label="Remove one">'+icon("minus")+'</button><b>'+x.qty+'</b><button data-action="pos-add" data-id="'+esc(x.p.sku)+'" class="cart-step" aria-label="Add one">'+icon("plus")+'</button></div><strong>'+money(x.p.price*x.qty)+'</strong></div>').join(""):'<div class="empty-state cart-empty">'+icon("shopping-basket")+'<strong>Your basket is empty</strong><span>Add a product to start a counter sale.</span></div>')+'</div><div class="pos-cart-bottom"><label class="pos-customer-label">PAYMENT METHOD<select data-change="pos-payment">'+["Cash","Mobile money","Card","Bank transfer"].map(p=>'<option '+(ui.posPayment===p?"selected":"")+'>'+p+'</option>').join("")+'</select></label><div class="pos-total-row"><span>Subtotal</span><strong>'+money(total)+'</strong></div><div class="pos-total-row"><span>Tax / fees</span><strong>Not configured</strong></div><div class="pos-total-row total-final"><span>Total due</span><strong>'+money(total)+'</strong></div><button class="btn btn-primary pos-checkout" data-action="pos-checkout" '+(!lines.length?"disabled":"")+'>'+icon("check-circle-2")+' Complete sale · '+money(total)+'</button><p class="pos-disclaimer">Demo only: this records a sale and deducts sample stock; it does not process a real payment.</p></div></aside></div>';
  }
  function completePosSale(){
    const keys=Object.keys(ui.cart);if(!keys.length){notify("Add at least one product to the basket.","error");return;}
    const lines=keys.map(sku=>{const p=data.inventory.find(x=>x.branch===ui.posBranch&&x.sku===sku);return p?{sku:p.sku,qty:ui.cart[sku],price:p.price,name:p.name,unit:p.unit,branch:p.branch}:null;}).filter(Boolean);
    for(const line of lines){const stock=data.inventory.find(x=>x.branch===ui.posBranch&&x.sku===line.sku);if(!stock||stock.qty<line.qty){notify("Not enough stock for "+line.name+". Adjust the basket or receive stock.","error");return;}}
    const total=Number(lines.reduce((sum,x)=>sum+x.price*x.qty,0).toFixed(2)),orderId="BMS-"+(1050+data.orders.length).toString();
    const input=$("#pos-customer");
    const order={id:orderId,customer:(input&&input.value.trim())||"Walk-in sale",phone:"—",branch:ui.posBranch,items:lines.map(x=>x.name+" · "+x.qty+" "+x.unit).join(", "),total:total,status:"Completed",payment:"Paid",payMethod:ui.posPayment,source:"In-store",time:new Date().toLocaleTimeString("en-GB",{hour:"2-digit",minute:"2-digit"}),area:"—",delivery:false,lines:lines,stockDeducted:true};
    for(const line of lines){const stock=data.inventory.find(x=>x.branch===ui.posBranch&&x.sku===line.sku);stock.qty=Number((stock.qty-line.qty).toFixed(2));createMovement("Counter sale deducted "+line.qty+" "+stock.unit+" "+stock.name+" · "+orderId,stock.branch,"Sale");}
    data.orders.unshift(order);data.extraSales=data.extraSales||{};data.extraSales[ui.posBranch]=(data.extraSales[ui.posBranch]||0)+total;data.extraOrderCounts=data.extraOrderCounts||{};data.extraOrderCounts[ui.posBranch]=(data.extraOrderCounts[ui.posBranch]||0)+1;
    syncStockAlerts();ui.cart={};save();notify("Sale "+orderId+" completed and stock deducted.");
  }
